//! Generated circuit rows. Oracles: the checker (tested against hand-broken designs in
//! `circuit_check.rs`): every generated design passes `check` and uses only the requested
//! features; the inverse: `parse(dump(d))` equals `d` (`eq_ignoring_spans`). Per element kind,
//! a set holding only that kind (plus the items and expression features every row needs), and
//! every kernel and circuit feature (the run owner's rows are
//! generated by the kernel's full-set harness); fixed seeds, printed on failure.
//!
//! Cites: `rewrite/IR-IMPL.md` §2 ("Round trip", "Generator").
//!
//! Contents: tests only.

#![cfg(feature = "gen")]

#[path = "circuit_common.rs"]
mod circuit_common;

#[cfg(test)]
mod tests {

    use super::circuit_common::{codes, full_set};

    use spicerack_ir::r#gen::{Size, generate};
    use spicerack_ir::{
        CircuitExtra, Design, Diags, ElemKind, ExprId, Feature, FeatureSet, ItemKind, ModelFamily,
        WaveKind, check, dump, features_used, parse,
    };

    const SIZE: Size = Size {
        items: 40,
        scope_depth: 2,
        expr_depth: 3,
        files: 1,
    };
    const SEEDS: [u64; 8] = [1, 2, 3, 5, 8, 13, 21, 0x5eed];

    /// Whether `f` belongs to the run owner (its rows are tested with the run owner's).
    fn run_owned(f: Feature) -> bool {
        match f {
            Feature::Item(k) => matches!(
                k,
                ItemKind::Statistics
                    | ItemKind::Analysis
                    | ItemKind::Loop
                    | ItemKind::Alter
                    | ItemKind::Option
                    | ItemKind::Env
                    | ItemKind::NodeSet
                    | ItemKind::Save
                    | ItemKind::Print
                    | ItemKind::Measure
            ),
            Feature::Analysis(_) | Feature::Run(_) | Feature::Option(_) => true,
            _ => false,
        }
    }

    /// Every kernel and circuit feature.
    fn circuit_set() -> FeatureSet {
        full_set()
            .iter()
            .filter(|&f| !run_owned(f))
            .fold(FeatureSet::EMPTY, FeatureSet::with)
    }

    /// Every kernel feature, `kind`, and the pulse wave; no circuit extra.
    fn only_kind(kind: ElemKind) -> FeatureSet {
        let base = circuit_set();
        let mut set = FeatureSet::EMPTY;
        for f in base.iter() {
            let keep = match f {
                Feature::Elem(k) => k == kind,
                Feature::Wave(w) => w == WaveKind::Pulse,
                Feature::Circuit(_) => false,
                _ => true,
            };
            if keep {
                set = set.with(f);
            }
        }
        set
    }

    fn valid_and_round_trips(seed: u64, set: &FeatureSet) {
        let d = generate(seed, set, SIZE);
        let mut diags = Diags::new();
        check(&d, &mut diags);
        assert!(diags.is_empty(), "seed {seed}: {:?}", codes(&diags));
        let extra = features_used(&d).minus(*set);
        assert!(
            extra.is_empty(),
            "seed {seed}: unrequested {:?}",
            extra.iter().collect::<Vec<_>>()
        );
        let mut text = String::new();
        for file in d.files() {
            dump(&d, file, &mut text);
        }
        let mut back = Design::new();
        let mut pd = Diags::new();
        parse(&text, &mut back.builder(), &mut pd);
        assert!(pd.is_empty(), "seed {seed}: {:?}\n{text}", codes(&pd));
        assert!(back.eq_ignoring_spans(&d), "seed {seed}:\n{text}");
    }

    #[test]
    fn each_element_kind_alone() {
        for kind in ElemKind::ALL {
            let set = only_kind(kind);
            for seed in SEEDS {
                valid_and_round_trips(seed ^ kind as u64, &set);
            }
        }
    }

    #[test]
    fn every_feature_on() {
        let set = circuit_set();
        for seed in SEEDS {
            valid_and_round_trips(seed, &set);
        }
    }

    /// Without `ElementWithoutModel` the generator still draws every masterless kind (they name
    /// no model and so need no feature), and no generated element of a kind with a master is bare.
    #[test]
    fn masterless_kinds_need_no_bare_feature() {
        let set = circuit_set()
            .minus(FeatureSet::EMPTY.with(Feature::Circuit(CircuitExtra::ElementWithoutModel)));
        let mut seen = FeatureSet::EMPTY;
        for seed in 0..2000u64 {
            let d = generate(seed, &set, SIZE);
            let used = features_used(&d);
            assert!(
                !used.contains(Feature::Circuit(CircuitExtra::ElementWithoutModel)),
                "seed {seed}"
            );
            seen = seen.union(used);
        }
        let missing: Vec<ElemKind> = ElemKind::ALL
            .into_iter()
            .filter(|k| k.master_kind().is_none() && *k != ElemKind::Unresolved)
            .filter(|k| !seen.contains(Feature::Elem(*k)))
            .collect();
        assert!(missing.is_empty(), "{missing:?}");
    }

    /// R61/A36: a generated instance bound to a subcircuit has as many terminals as its ports
    /// (oracle: the bound `Subckt` row), over the full set.
    #[test]
    fn a_generated_instance_matches_its_masters_ports() {
        // the floor is on the instances seen, not the seeds (the stream shifts with the
        // generators): the walk stops once it has checked `WANT`
        const WANT: usize = 20;
        let mut bound = 0;
        for seed in 0..4000u64 {
            if bound >= WANT {
                break;
            }
            let d = generate(seed, &circuit_set(), SIZE);
            for (item, _) in d.reachable() {
                if item.kind != ItemKind::Element {
                    continue;
                }
                let e: spicerack_ir::Element = d.row(item.index);
                if e.kind != ElemKind::Instance || e.model.def.is_none() {
                    continue;
                }
                let def = d.def(e.model.def);
                let ports = d.row::<spicerack_ir::item::Subckt>(def.item.index).ports;
                bound += 1;
                assert_eq!(e.terminals.len(), ports.len(), "seed {seed}");
            }
        }
        assert!(bound >= WANT, "the property saw {bound} bound instances");
    }

    /// A33 (the lead's ruling): a set without `BehavUntypedParam` but with the dynamic
    /// `ToReal` still reads parameters in behavioural expressions, every read typed: some
    /// generated behavioural source reads `to_real(…)` or `to_int(…)` of a parameter, and no
    /// design states the feature (oracle: the IR text and `features_used`).
    #[test]
    fn a_behavioural_source_reads_typed_parameters_without_the_feature() {
        let set = circuit_set()
            .minus(FeatureSet::EMPTY.with(Feature::Circuit(CircuitExtra::BehavUntypedParam)));
        // the floor is on the reads, not the seeds: the stream shifts whenever a generator
        // changes, so the walk runs until it has seen `WANT` typed reads, within `SEEDS`
        const WANT: usize = 10;
        const SEEDS: u64 = 6000;
        let mut typed = 0;
        for seed in 0..SEEDS {
            if typed >= WANT {
                break;
            }
            let d = generate(seed, &set, SIZE);
            assert!(
                !features_used(&d).contains(Feature::Circuit(CircuitExtra::BehavUntypedParam)),
                "seed {seed}"
            );
            let mut text = String::new();
            for f in d.files() {
                dump(&d, f, &mut text);
            }
            typed += text
                .lines()
                .filter(|l| l.trim_start().starts_with("element behav "))
                .filter(|l| typed_read(l))
                .count();
        }
        assert!(
            typed >= WANT,
            "{typed} behavioural sources read a typed parameter in {SEEDS} seeds"
        );
    }

    /// Whether `line` holds `to_real(name)` or `to_int(name)` of a bare name: a typed
    /// parameter read.
    fn typed_read(line: &str) -> bool {
        ["to_real(", "to_int("].iter().any(|call| {
            line.match_indices(call).any(|(at, _)| {
                let rest = &line[at + call.len()..];
                let name: String = rest
                    .chars()
                    .take_while(|c| c.is_ascii_alphanumeric() || *c == '_')
                    .collect();
                !name.is_empty()
                    && !name.starts_with(|c: char| c.is_ascii_digit())
                    && rest[name.len()..].starts_with(')')
            })
        })
    }

    /// A28 item 5: under `Params::TypedOnly` every generated element has an empty instance
    /// parameter list and every model an empty parameter list, over the full feature set, and the
    /// designs still check clean (oracle: the rows themselves and `check`).
    #[test]
    fn typed_only_generates_no_parameter_list() {
        use spicerack_ir::r#gen::{Params, generate_with};
        let mut models = 0;
        for seed in 0..300u64 {
            let d = generate_with(seed, &FeatureSet::ALL, SIZE, Params::TypedOnly);
            for (item, _) in d.reachable() {
                match item.kind {
                    ItemKind::Element => {
                        let e: spicerack_ir::Element = d.row(item.index);
                        assert!(e.params.is_empty(), "seed {seed}: element params");
                    }
                    ItemKind::Model => {
                        models += 1;
                        let m: spicerack_ir::Model = d.row(item.index);
                        assert!(m.params.is_empty(), "seed {seed}: model params");
                    }
                    _ => {}
                }
            }
            let mut diags = Diags::new();
            check(&d, &mut diags);
            assert_eq!(codes(&diags), Vec::new(), "seed {seed}");
        }
        assert!(models > 50, "the property saw {models} models");
    }

    /// The generator's version vocabulary: a model of a versioned family draws its version from
    /// the standard's published versions where a simulator's list is known. Oracle: ngspice-45's
    /// accepted versions per family as `ng-models` read them (parser/inpdomod.c, b3v32set.c:86-92,
    /// b3check.c:49, b4v5check.c:64-69, b4v6check.c:815, b4v7check.c:834, b4check.c:68-70,
    /// hsmhvset.c:76-81, hsmhv2set.c:136-150, hsm2set.c:132-138, hicum2setup.c:45, b4soiset.c:124,
    /// b3soi{fd,dd,pd}set.c:69, vbicsetup.c:360; the model standards' versions by ngspice's device
    /// descriptions where its parameter differs: HiSIM 2.8.0, B3SOI-FD/DD 2.1, -PD 2.2.3, B4SOI 4.4.0), and VACASK 36be560's as `vc-devices` read them
    /// (VBIC 1.3, PSP 103.4, BSIM-BULK 106: module files), written here by hand.
    #[test]
    fn a_versioned_model_draws_a_published_version() {
        let lists: [(ModelFamily, &[&str]); 12] = [
            (
                ModelFamily::Bsim3,
                &["3.0", "3.1", "3.2", "3.2.2", "3.2.3", "3.2.4", "3.3.0"],
            ),
            (
                ModelFamily::Bsim4,
                &[
                    "4.0.0", "4.1.0", "4.2.0", "4.3.0", "4.4.0", "4.5.0", "4.6.5", "4.7.0",
                    "4.8.0", "4.8.1", "4.8.2", "4.8.3",
                ],
            ),
            (ModelFamily::HisimHv, &["1.24", "2.20"]),
            (ModelFamily::Hisim2, &["2.8.0"]),
            (ModelFamily::Hicum2, &["2.4.0"]),
            (ModelFamily::B4Soi, &["4.4.0"]),
            (ModelFamily::B3SoiFd, &["2.1"]),
            (ModelFamily::B3SoiDd, &["2.1"]),
            (ModelFamily::B3SoiPd, &["2.2.3"]),
            (ModelFamily::Vbic, &["1.2", "1.3"]),
            (ModelFamily::Psp103, &["103.4"]),
            (ModelFamily::BsimBulk, &["106"]),
        ];
        let set = circuit_set();
        let mut seen = 0;
        for seed in 0..1000u64 {
            let d = generate(seed, &set, SIZE);
            for (item, _) in d.reachable() {
                if item.kind != ItemKind::Model {
                    continue;
                }
                let m: spicerack_ir::Model = d.row(item.index);
                let Some((_, list)) = lists.iter().find(|l| l.0 == m.family) else {
                    continue;
                };
                seen += 1;
                let text = match (m.version != ExprId::NONE).then(|| d.expr(m.version)) {
                    Some(spicerack_ir::Expr::Str(s)) => d.str(s).to_string(),
                    other => panic!("seed {seed}: {:?} version {other:?}", m.family),
                };
                assert!(
                    list.contains(&text.as_str()),
                    "seed {seed}: {:?} {text}",
                    m.family
                );
            }
        }
        assert!(seen > 20, "the property saw {seen} listed models");
    }

    /// A25: given a set without `Family(F)`, the generator makes no library of F.
    #[test]
    fn no_library_of_a_family_the_set_lacks() {
        let set = circuit_set().minus(FeatureSet::EMPTY.with(Feature::Family(ModelFamily::Bsim4)));
        let mut libraries = 0;
        for seed in 0..400u64 {
            let d = generate(seed, &set, SIZE);
            for (item, _) in d.reachable() {
                if item.kind == ItemKind::DeviceLibrary {
                    libraries += 1;
                    let family = d.row::<spicerack_ir::DeviceLibrary>(item.index).family;
                    assert_ne!(family, ModelFamily::Bsim4, "seed {seed}");
                }
            }
        }
        assert!(libraries > 0, "the property saw a library");
    }

    #[test]
    fn the_full_set_reaches_every_circuit_kind_and_extra() {
        let set = circuit_set();
        let mut seen = FeatureSet::EMPTY;
        for seed in 0..4000u64 {
            let d = generate(seed, &set, SIZE);
            seen = seen.union(features_used(&d));
        }
        let mut missing = Vec::new();
        for k in ElemKind::ALL {
            if !seen.contains(Feature::Elem(k)) {
                missing.push(format!("{k:?}"));
            }
        }
        for w in WaveKind::ALL {
            if !seen.contains(Feature::Wave(w)) {
                missing.push(format!("{w:?}"));
            }
        }
        for x in CircuitExtra::ALL {
            if !seen.contains(Feature::Circuit(x)) {
                missing.push(format!("{x:?}"));
            }
        }
        assert!(seen.contains(Feature::Item(ItemKind::Model)));
        assert!(seen.contains(Feature::Item(ItemKind::DeviceLibrary)));
        // A15 C4: some generated instance binds to a bin group's definition
        let grouped = (0..4000u64).any(|seed| {
            let d = generate(seed, &set, SIZE);
            let groups: Vec<spicerack_ir::DefId> = d
                .definitions_all()
                .iter()
                .enumerate()
                .filter(|(_, def)| def.kind == spicerack_ir::DefKind::Model)
                .filter(|(_, def)| d.row::<spicerack_ir::Model>(def.item.index).name != def.name)
                .map(|(k, _)| spicerack_ir::DefId(k as u32))
                .collect();
            d.reachable().iter().any(|&(item, _)| {
                item.kind == ItemKind::Element
                    && groups.contains(&d.row::<spicerack_ir::Element>(item.index).model.def)
            })
        });
        assert!(grouped, "no seed bound an instance to a bin group");
        assert_eq!(missing, Vec::<String>::new());
    }

    /// A15 K5: with only `Family(Resistor)` of all families in the set, every generated model
    /// is a resistor model, and some seed makes one.
    #[test]
    fn models_only_of_requested_families() {
        let set = circuit_set()
            .iter()
            .filter(|&f| !matches!(f, Feature::Family(m) if m != ModelFamily::Resistor))
            .fold(FeatureSet::EMPTY, FeatureSet::with);
        let mut made = false;
        for seed in SEEDS {
            let d = generate(seed, &set, SIZE);
            let extra = features_used(&d).minus(set);
            assert!(
                extra.is_empty(),
                "seed {seed}: unrequested {:?}",
                extra.iter().collect::<Vec<_>>()
            );
            made |= features_used(&d).contains(Feature::Family(ModelFamily::Resistor));
        }
        assert!(made, "no seed made a resistor model");
    }

    /// R48 (d): a generated element that names a model mostly names one the design defines,
    /// visible from it (the generator binds it; `check` confirms the binding is legal).
    /// Oracle: the share of elements with a bound model, per kind that takes a model, over
    /// 1500 seeds of the circuit set, against a floor; each kind is seen often enough to count.
    #[test]
    fn a_named_model_mostly_exists() {
        const FLOOR: f64 = 0.6;
        // the rarest kinds (a source naming a builtin model) are seen 20 to 30 times here: a
        // source with no visible model is now bare, not a fresh name, so 1500 seeds
        const SEEN_MIN: u32 = 12;
        let mut named = [0u32; ElemKind::COUNT];
        let mut bound = [0u32; ElemKind::COUNT];
        for seed in 0..1500u64 {
            let d = generate(seed, &circuit_set(), SIZE);
            for (item, _) in d.reachable() {
                if item.kind != ItemKind::Element {
                    continue;
                }
                let e: spicerack_ir::Element = d.row(item.index);
                let takes_model = e.kind.master_kind() == Some(spicerack_ir::DefKind::Model);
                if takes_model && !e.model.name.is_none() {
                    named[e.kind as usize] += 1;
                    bound[e.kind as usize] += u32::from(e.model.is_resolved());
                }
            }
        }
        let mut low = Vec::new();
        for kind in ElemKind::ALL {
            if kind.master_kind() != Some(spicerack_ir::DefKind::Model) {
                continue;
            }
            let (n, k) = (named[kind as usize], bound[kind as usize]);
            if n < SEEN_MIN || f64::from(k) < FLOOR * f64::from(n) {
                low.push(format!("{kind:?}: {k} of {n} bound"));
            }
        }
        assert!(
            low.is_empty(),
            "below {FLOOR} or seen under {SEEN_MIN} times: {low:?}"
        );
    }

    /// An element whose model is optional (a passive, an independent or controlled source, a
    /// lossless line) is drawn bare or bound to a visible model of its family, never with a
    /// fresh name no statement defines: no simulator runs `capacitor c1 (a 0) model=g30` with no
    /// `g30` anywhere, and such a draw starves the laws of the kind (vacask-2, seed 1). A kind
    /// that needs a model may still name an absent one (R48 d: an absent kit stays legal).
    #[test]
    fn an_optional_model_is_bare_or_bound() {
        let optional = [
            ElemKind::Resistor,
            ElemKind::Capacitor,
            ElemKind::Inductor,
            ElemKind::VSource,
            ElemKind::ISource,
            ElemKind::Vcvs,
            ElemKind::Vccs,
            ElemKind::Cccs,
            ElemKind::Ccvs,
            ElemKind::LosslessLine,
        ];
        // with bare elements allowed, and without (VACASK's set: every instance names a model)
        let strict = full_set()
            .minus(FeatureSet::EMPTY.with(Feature::Circuit(CircuitExtra::ElementWithoutModel)));
        for (seed, set) in (0..300u64).flat_map(|s| [(s, full_set()), (s, strict)]) {
            let d = generate(seed, &set, SIZE);
            for (item, _) in d.reachable() {
                if item.kind != ItemKind::Element {
                    continue;
                }
                let e: spicerack_ir::Element = d.row(item.index);
                let fresh = !e.model.name.is_none() && !e.model.is_resolved();
                assert!(
                    !(optional.contains(&e.kind) && fresh),
                    "seed {seed}: {:?} {} names the undefined model {}",
                    e.kind,
                    d.str(e.name),
                    d.str(e.model.name)
                );
            }
        }
    }
}
